@pytest.mark.pre_alloc_mutable
def test_gas_cost_mem_seg(
    state_test: StateTestFiller,
    pre: Alloc,
    fork: Fork,
    d: int,
    g: int,
    v: int,
) -> None:
    """Ori Pomerantz qbzzt1@gmail."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = EOA(
        key=0x40ac0fc28c27e961ee46ec43355a094de205856edbd4654cf2577c2608d4ec1e
    )

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        difficulty=0x20000,
        base_fee_per_gas=10,
        gas_limit=100000000,
    )

    # Source: lll
    # {
    #   ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
    #   ; Initialization
    # 
    #   ; Variables (0x20 byte wide)
    #   (def 'gasB4             0x000)  ; Before the action being measured
    #   (def 'gasAfter          0x020)  ; After the action being measured
    # 
    #   (def 'afterVars         0x100)  ; Memory after the variables,
    #                                   ; safe to copy into
    # 
    #   ; Understand CALLDATA. It is four bytes of function
    #   ; selector (irrelevant) followed by 32 byte words
    #   ; of the parameters
    #   (def 'opcode     $4 )
    #   (def 'length     $36)
    #   (def 'expectedCost $68)
    # 
    #   ; NOP for if statements
    #   (def 'NOP     0)
    # 
    #   ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
    #   ; Run the operation
    # 
    #   ; SHA3
    #   (if (= opcode 0x20) {
    #       [gasB4]    (gas)
    #       (sha3 0 length)
    #       [gasAfter] (gas)
    #   } NOP)
    # ... (70 more lines)
    target = pre.deploy_contract(
        code=Op.JUMPI(pc=Op.PUSH2[0x11], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0x20))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0x21]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.POP(Op.SHA3(offset=0x0, size=Op.CALLDATALOAD(offset=0x24)))
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=Op.PUSH2[0x33], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0x37))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0x45]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.CALLDATACOPY(dest_offset=0x100, offset=0x0, size=Op.CALLDATALOAD(offset=0x24))
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=Op.PUSH2[0x57], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0x39))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0x69]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.CODECOPY(dest_offset=0x100, offset=0x0, size=Op.CALLDATALOAD(offset=0x24))
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=Op.PUSH2[0x7b], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0xa0))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0x8a]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.LOG0(offset=0x0, size=Op.CALLDATALOAD(offset=0x24))
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=Op.PUSH2[0x9c], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0xa1))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0xad]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.LOG1(offset=0x0, size=Op.CALLDATALOAD(offset=0x24), topic_1=0x1)
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=Op.PUSH2[0xbf], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0xa2))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0xd2]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.LOG2(offset=0x0, size=Op.CALLDATALOAD(offset=0x24), topic_1=0x1, topic_2=0x2)
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=Op.PUSH2[0xe4], condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0xa3))
        + Op.POP(0x0) + Op.JUMP(pc=Op.PUSH2[0xf9]) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.LOG3(offset=0x0, size=Op.CALLDATALOAD(offset=0x24), topic_1=0x1, topic_2=0x2, topic_3=0x3)
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.JUMPI(pc=0x10b, condition=Op.EQ(Op.CALLDATALOAD(offset=0x4), 0xa4))
        + Op.POP(0x0) + Op.JUMP(pc=0x122) + Op.JUMPDEST
        + Op.MSTORE(offset=0x0, value=Op.GAS)
        + Op.LOG4(offset=0x0, size=Op.CALLDATALOAD(offset=0x24), topic_1=0x1, topic_2=0x2, topic_3=0x3, topic_4=0x4)
        + Op.MSTORE(offset=0x20, value=Op.GAS) + Op.JUMPDEST
        + Op.SSTORE(key=0x0, value=Op.SUB(Op.SUB(Op.MLOAD(offset=0x0), Op.MLOAD(offset=0x20)), Op.CALLDATALOAD(offset=0x44)))  # noqa: E501
        + Op.STOP,
        storage={0: 24743},
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        address=Address("0x727437e50af8535411157a4aca154c81d72baad4"),  # noqa: E501
    )
    pre[sender] = Account(balance=0xba1a9ce0ba1a9ce)

    expect_entries_: list[dict] = [
        {
            "indexes": {'data': -1, 'gas': -1, 'value': -1},
            "network": ['>=Cancun'],
            "result": {target: Account(storage={0: 0})},
        },
    ]

    post, _exc = resolve_expect_post(expect_entries_, d, g, v, fork)

    tx = Transaction(
        sender=sender,
        to=target,
        data=_tx_data(d),
        gas_limit=TX_GAS[g],
        value=TX_VALUE[v],
        nonce=0,
        gas_price=10,
        error=_exc,
    )


    state_test(env=env, pre=pre, post=post, tx=tx)
